      const view=new DataView(bytes.buffer); let offset=8;
      while(offset+8<=bytes.length){const size=view.getUint32(offset);const type=text.slice(offset+4,offset+8);if(type==='acTL')throw new Error('Animated PNG is not converted. Keep the original animation.');if(type==='IDAT')break;offset+=size+12;}
