  /* ------------------------------------------------------------------ */
  /* Saving files                                                       */
  /* ------------------------------------------------------------------ */
  async function saveFile(name, blob) {
    const a = el('a', { href: URL.createObjectURL(blob), download: name });
    document.body.append(a);
    a.click();
    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 2000);
    announce('Saved ' + name + '.');
  }

  /* ------------------------------------------------------------------ */
  /* State and rendering                                                */
  /* ------------------------------------------------------------------ */
